files.bin/certs.sh:
#!/bin/sh
set -eu
. ./lib/actions.sh
case "${1:-help}" in
    issue) cert_issue ;;
    renew) cert_renew ;;
    revoke) cert_revoke ;;
    inspect) cert_inspect ;;
    help) cert_help ;;
    *) printf '%s\n' 'unknown command' >&2; exit 64 ;;
esac

files.lib/actions.sh:
cert_issue() { printf '%s\n' 'issue requested'; }
cert_renew() { printf '%s\n' 'renew requested'; }
cert_revoke() { printf '%s\n' 'revoke requested'; }
cert_inspect() { printf '%s\n' 'inspect requested'; }
cert_help() { cat docs/commands.md; }
